/**
 * Pre-bundled ScalePods Official Letterhead Background (A4 JPEG, 2480x3508).
 * Inlined as base64 so Next.js / Vercel bundles it seamlessly without filesystem dependencies.
 */
export const SCALEPODS_LETTERHEAD_BASE64 =
  "";

let cachedBuffer: Buffer | null = null;

export function getDefaultLetterheadBuffer(): Buffer {
  if (!cachedBuffer) {
    cachedBuffer = Buffer.from(SCALEPODS_LETTERHEAD_BASE64, "base64");
  }
  return cachedBuffer;
}
